import{_ as e,o as l,c as a,a5 as d}from"./chunks/framework.a5no_H3L.js";const o=JSON.parse('{"title":"常用参数速查","description":"本页只记录参数用途、默认值和适用范围。参数背后的机制与调优方法见性能调优和首次生产部署。","frontmatter":{},"headers":[],"relativePath":"mysql/reference/parameters.md","filePath":"mysql/reference/parameters.md"}'),r={name:"mysql/reference/parameters.md"};function s(i,t,n,c,f,m){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="常用参数速查" tabindex="-1" data-src-line="1" data-src-file="mysql/reference/parameters.md">常用参数速查 <a class="header-anchor" href="#常用参数速查" aria-label="Permalink to &quot;常用参数速查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/reference/parameters.md"><p data-src-line="3" data-src-file="mysql/reference/parameters.md">本页只记录参数用途、默认值和适用范围。参数背后的机制与调优方法见<a href="./../10-practice/chapter-05-performance-tuning.html">性能调优</a>和<a href="./../10-practice/chapter-03-first-production.html">首次生产部署</a>。</p></blockquote><blockquote data-src-line="5" data-src-file="mysql/reference/parameters.md"><p data-src-line="5" data-src-file="mysql/reference/parameters.md">参数按功能分类，默认值以 MySQL 8.0 为基线；“配置原则”不是可直接套用的生产值。版本和小版本差异请用 <code>SHOW VARIABLES LIKE</code> 或官方文档确认。</p></blockquote><h2 id="连接与线程" tabindex="-1" data-src-line="7" data-src-file="mysql/reference/parameters.md">连接与线程 <a class="header-anchor" href="#连接与线程" aria-label="Permalink to &quot;连接与线程&quot;">​</a></h2><table tabindex="0"><thead data-src-line="9" data-src-file="mysql/reference/parameters.md"><tr data-src-line="9" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">配置原则</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="11" data-src-file="mysql/reference/parameters.md"><tr data-src-line="11" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>max_connections</code></td><td style="text-align:left;">151</td><td style="text-align:left;">按应用总峰值、管理与复制连接规划，并保留余量</td><td style="text-align:left;">最大连接数；调大前先排除连接泄漏</td></tr><tr data-src-line="12" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>max_connect_errors</code></td><td style="text-align:left;">100</td><td style="text-align:left;">根据网络和客户端行为评估</td><td style="text-align:left;">连续连接失败达到阈值后拒绝该主机，直到执行 <code>FLUSH HOSTS</code></td></tr><tr data-src-line="13" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>wait_timeout</code></td><td style="text-align:left;">28800</td><td style="text-align:left;">与连接池空闲策略协调</td><td style="text-align:left;">非交互式连接空闲超时（秒）</td></tr><tr data-src-line="14" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>interactive_timeout</code></td><td style="text-align:left;">28800</td><td style="text-align:left;">与交互会话需求协调</td><td style="text-align:left;">交互式连接空闲超时（秒）</td></tr><tr data-src-line="15" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>thread_cache_size</code></td><td style="text-align:left;">-1（自动设置）</td><td style="text-align:left;">根据 <code>Threads_created/Connections</code> 观察调整</td><td style="text-align:left;">线程缓存，减少线程创建开销；不要把 -1 当作固定缓存数</td></tr></tbody></table><h2 id="innodb-缓冲池" tabindex="-1" data-src-line="17" data-src-file="mysql/reference/parameters.md">InnoDB 缓冲池 <a class="header-anchor" href="#innodb-缓冲池" aria-label="Permalink to &quot;InnoDB 缓冲池&quot;">​</a></h2><table tabindex="0"><thead data-src-line="19" data-src-file="mysql/reference/parameters.md"><tr data-src-line="19" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="21" data-src-file="mysql/reference/parameters.md"><tr data-src-line="21" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_size</code></td><td style="text-align:left;">128M</td><td style="text-align:left;">独占服务器常从物理内存的 60%~80% 开始压测</td><td style="text-align:left;">缓冲池容量；共享主机需为系统和其他进程保留内存</td></tr><tr data-src-line="22" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_instances</code></td><td style="text-align:left;">1</td><td style="text-align:left;">与缓冲池容量和并发模型共同评估</td><td style="text-align:left;">缓冲池分片数；实例数越多，每个分片越小</td></tr><tr data-src-line="23" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_dump_at_shutdown</code></td><td style="text-align:left;">ON</td><td style="text-align:left;">ON</td><td style="text-align:left;">关闭时保存热数据索引</td></tr><tr data-src-line="24" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_buffer_pool_load_at_startup</code></td><td style="text-align:left;">ON</td><td style="text-align:left;">ON</td><td style="text-align:left;">启动时加载热数据索引</td></tr></tbody></table><h2 id="redo-log" tabindex="-1" data-src-line="26" data-src-file="mysql/reference/parameters.md">Redo Log <a class="header-anchor" href="#redo-log" aria-label="Permalink to &quot;Redo Log&quot;">​</a></h2><table tabindex="0"><thead data-src-line="28" data-src-file="mysql/reference/parameters.md"><tr data-src-line="28" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="30" data-src-file="mysql/reference/parameters.md"><tr data-src-line="30" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_redo_log_capacity</code></td><td style="text-align:left;">100M</td><td style="text-align:left;">1G~4G</td><td style="text-align:left;">Redo Log 总大小（8.0.30+）</td></tr><tr data-src-line="31" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_flush_log_at_trx_commit</code></td><td style="text-align:left;">1</td><td style="text-align:left;">生产默认保留 1</td><td style="text-align:left;">1 表示每次提交刷 Redo；2 表示每秒刷盘，进程或系统崩溃时可能丢失已提交事务</td></tr><tr data-src-line="32" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>innodb_log_buffer_size</code></td><td style="text-align:left;">16M</td><td style="text-align:left;">64M~256M</td><td style="text-align:left;">日志缓冲区大小</td></tr></tbody></table><h2 id="binlog" tabindex="-1" data-src-line="34" data-src-file="mysql/reference/parameters.md">Binlog <a class="header-anchor" href="#binlog" aria-label="Permalink to &quot;Binlog&quot;">​</a></h2><table tabindex="0"><thead data-src-line="36" data-src-file="mysql/reference/parameters.md"><tr data-src-line="36" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="38" data-src-file="mysql/reference/parameters.md"><tr data-src-line="38" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>log_bin</code></td><td style="text-align:left;">取决于发行版与启动方式</td><td style="text-align:left;">复制、PITR 或审计场景按方案启用</td><td style="text-align:left;">Binlog 总开关；启用前评估磁盘、网络和保留策略</td></tr><tr data-src-line="39" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>binlog_format</code></td><td style="text-align:left;">ROW</td><td style="text-align:left;">ROW</td><td style="text-align:left;">推荐 ROW 格式</td></tr><tr data-src-line="40" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>binlog_expire_logs_seconds</code></td><td style="text-align:left;">2592000</td><td style="text-align:left;">不早于备份和恢复演练要求的最短时长</td><td style="text-align:left;">Binlog 保留时间（秒）</td></tr><tr data-src-line="41" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>sync_binlog</code></td><td style="text-align:left;">1</td><td style="text-align:left;">需要耐受崩溃时保持 1</td><td style="text-align:left;">每 N 次提交同步 Binlog；大于 1 可提升吞吐，但系统崩溃时可能丢失已提交事务</td></tr></tbody></table><h2 id="查询与排序" tabindex="-1" data-src-line="43" data-src-file="mysql/reference/parameters.md">查询与排序 <a class="header-anchor" href="#查询与排序" aria-label="Permalink to &quot;查询与排序&quot;">​</a></h2><table tabindex="0"><thead data-src-line="45" data-src-file="mysql/reference/parameters.md"><tr data-src-line="45" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="47" data-src-file="mysql/reference/parameters.md"><tr data-src-line="47" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>sort_buffer_size</code></td><td style="text-align:left;">256K</td><td style="text-align:left;">仅对可证明受益的会话增大</td><td style="text-align:left;">每个需要排序的线程分配，不能无条件全局调大</td></tr><tr data-src-line="48" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>join_buffer_size</code></td><td style="text-align:left;">256K</td><td style="text-align:left;">仅对无索引连接的热点查询评估</td><td style="text-align:left;">每个未使用索引的连接分配</td></tr><tr data-src-line="49" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>tmp_table_size</code></td><td style="text-align:left;">16M</td><td style="text-align:left;">与 <code>max_heap_table_size</code> 同步评估</td><td style="text-align:left;">内存临时表大小上限</td></tr><tr data-src-line="50" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>max_heap_table_size</code></td><td style="text-align:left;">16M</td><td style="text-align:left;">与 <code>tmp_table_size</code> 同步评估</td><td style="text-align:left;">MEMORY/内部内存表大小上限；两者取较小值生效</td></tr><tr data-src-line="51" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>long_query_time</code></td><td style="text-align:left;">10</td><td style="text-align:left;">按业务延迟目标和采样开销设置</td><td style="text-align:left;">慢查询阈值（秒）</td></tr><tr data-src-line="52" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>slow_query_log</code></td><td style="text-align:left;">OFF</td><td style="text-align:left;">ON</td><td style="text-align:left;">开启慢查询日志</td></tr></tbody></table><h2 id="字符集与排序规则" tabindex="-1" data-src-line="54" data-src-file="mysql/reference/parameters.md">字符集与排序规则 <a class="header-anchor" href="#字符集与排序规则" aria-label="Permalink to &quot;字符集与排序规则&quot;">​</a></h2><table tabindex="0"><thead data-src-line="56" data-src-file="mysql/reference/parameters.md"><tr data-src-line="56" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="58" data-src-file="mysql/reference/parameters.md"><tr data-src-line="58" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>character_set_server</code></td><td style="text-align:left;">utf8mb4</td><td style="text-align:left;">utf8mb4</td><td style="text-align:left;">服务端字符集</td></tr><tr data-src-line="59" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>collation_server</code></td><td style="text-align:left;">utf8mb4_0900_ai_ci</td><td style="text-align:left;">utf8mb4_0900_ai_ci</td><td style="text-align:left;">服务端排序规则</td></tr></tbody></table><h2 id="安全" tabindex="-1" data-src-line="61" data-src-file="mysql/reference/parameters.md">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><table tabindex="0"><thead data-src-line="63" data-src-file="mysql/reference/parameters.md"><tr data-src-line="63" data-src-file="mysql/reference/parameters.md"><th style="text-align:left;">参数</th><th style="text-align:left;">默认值</th><th style="text-align:left;">推荐值</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="65" data-src-file="mysql/reference/parameters.md"><tr data-src-line="65" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>local_infile</code></td><td style="text-align:left;">OFF</td><td style="text-align:left;">保持 OFF，除非有明确迁移需求</td><td style="text-align:left;">控制客户端 <code>LOAD DATA LOCAL INFILE</code>；开启时同时限制客户端和服务器侧能力</td></tr><tr data-src-line="66" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>--symbolic-links</code></td><td style="text-align:left;">OFF</td><td style="text-align:left;">保持默认关闭</td><td style="text-align:left;">控制 MyISAM 符号链接支持；该选项已弃用，不是 <code>skip_symbolic_links</code> 系统变量</td></tr><tr data-src-line="67" data-src-file="mysql/reference/parameters.md"><td style="text-align:left;"><code>sql_mode</code></td><td style="text-align:left;"><code>ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION</code></td><td style="text-align:left;">优先保留官方默认值</td><td style="text-align:left;">兼容旧 SQL 而删除保护模式时，应先修正规则和查询，并记录临时兼容范围</td></tr></tbody></table><p data-src-line="69" data-src-file="mysql/reference/parameters.md">参数变更前记录当前值、来源（配置文件或 <code>SET PERSIST</code>）、版本和变更目的。按同一组指标做变更前后对比，避免一次同时修改多个互相关联的参数。</p>',18)])])}const g=e(r,[["render",s]]);export{o as __pageData,g as default};
